async function load() {
  list.replaceChildren();
  const projects = await request('/api/projects');
  for (const project of projects) {
    if (Boolean(project.archived) !== (filter.value === 'Archived')) continue;
    const row = document.createElement('li'); row.dataset.testid = 'project-row';
    const name = document.createElement('span'); name.className = 'project-name'; name.textContent = project.name;
    const summary = document.createElement('span'); summary.dataset.testid = 'project-summary'; summary.textContent = `${project.completedCount}/${project.totalCount} completed`;
    const actions = document.createElement('div'); actions.className = 'project-actions';
    const open = document.createElement('button'); open.type = 'button'; open.textContent = 'Open project';
    open.addEventListener('click', () => location.assign(`/projects/${escapePath(project.id)}`));
    const toggle = document.createElement('button'); toggle.type = 'button'; toggle.textContent = project.archived ? 'Restore project' : 'Archive project';
    toggle.addEventListener('click', async () => { await request(`/api/projects/${project.id}/${project.archived ? 'restore' : 'archive'}`, { method: 'POST' }); await load(); });
    actions.append(open, toggle); row.append(name, summary, actions); list.append(row);
  }
}
